<?php
declare(strict_types=1);
require __DIR__.'/../vendor/autoload.php';
use Magebean\Engine\{CheckOutcome,CheckResult,MagebeanRiskObservation,RequirementAssessmentEvaluator,RequirementOutcome};
$count=0;$assert=static function(bool $v,string $why)use(&$count):void{$count++;if(!$v)throw new RuntimeException($why);};
$base=['id'=>'MB-9998','revision'=>1,'family'=>'magebean','review_state'=>'accepted_scoped_criterion','human_evidence'=>['required'=>false],
 'obligations'=>[['id'=>'O1','op'=>'all','role'=>'mandatory','proof'=>'verified_predicate','checks'=>[['name'=>'source']]]]];
$fail=CheckResult::of(CheckOutcome::Fail,'Exact source call violates policy.',['violations'=>[['file'=>'app/code/Module/File.php','line'=>12]]],'SOURCE_POLICY_VIOLATION','source');
$gap=CheckResult::of(CheckOutcome::Unknown,'[UNKNOWN] A source file could not be read.',['violations'=>[['file'=>'do-not-promote.php','line'=>1]]],'SOURCE_POLICY_INCOMPLETE','gap');
$pass=CheckResult::of(CheckOutcome::Pass,'Every collected file meets policy.',[],'SOURCE_POLICY_SATISFIED','source');
$assessment=RequirementAssessmentEvaluator::evaluate($base,static fn()=>$fail);$before=serialize($assessment);
$risk=MagebeanRiskObservation::fromAssessment($base,$assessment);
$assert($risk['needs_attention']&&count($risk['findings'])===1,'Known violation produces actual check finding');
$assert($risk['assessment_outcome']==='FAIL'&&$risk['collection_complete'],'Complete failed observation remains complete');
$assert($risk['findings'][0]['message']===$fail->message&&$risk['findings'][0]['reason_code']===$fail->reasonCode,'Actual check message/reason retained');
$assert($risk['findings'][0]['evidence']===$fail->evidence,'Existing redacted check evidence retained exactly');
$assert(serialize($assessment)===$before,'Projection does not mutate assessment');
$heuristic=$base;$heuristic['obligations'][0]['proof']='heuristic';$heuristic['obligations'][0]['checks'][]=['name'=>'gap'];
$assessment=RequirementAssessmentEvaluator::evaluate($heuristic,static fn(string $name)=>$name==='gap'?$gap:$fail);
$risk=MagebeanRiskObservation::fromAssessment($heuristic,$assessment);
$assert($assessment->outcome===RequirementOutcome::Unknown&&$risk['assessment_outcome']==='UNKNOWN','Heuristic assessment stays UNKNOWN');
$assert($risk['needs_attention']&&count($risk['findings'])===1,'Actual issue remains actionable while UNKNOWN is diagnostic-only');
$assert(!$risk['collection_complete']&&count($risk['collection_gaps'])===1,'Failure and independent collection gap coexist');
$risk=MagebeanRiskObservation::fromAssessment($base,RequirementAssessmentEvaluator::evaluate($base,static fn()=>$pass));
$assert(!$risk['needs_attention']&&$risk['findings']===[]&&$risk['collection_gaps']===[]&&$risk['collection_complete'],'Clean assessment has no manufactured risk');
$risk=MagebeanRiskObservation::fromAssessment($base,RequirementAssessmentEvaluator::evaluate($base,static fn()=>$gap));
$assert(!$risk['needs_attention']&&$risk['findings']===[],'UNKNOWN never becomes an ordinary risk finding');
$assert(!$risk['collection_complete']&&count($risk['collection_gaps'])===1,'Gap-only observation remains visible');
$alternative=$base;$alternative['obligations'][0]['op']='any';$alternative['obligations'][0]['checks']=[['name'=>'first'],['name'=>'second']];
$assessment=RequirementAssessmentEvaluator::evaluate($alternative,static fn(string $name)=>$name==='first'?$fail:$pass);
$risk=MagebeanRiskObservation::fromAssessment($alternative,$assessment);
$assert($assessment->outcome===RequirementOutcome::Pass&&!$risk['needs_attention']&&$risk['findings']===[],'Verified passing alternative suppresses failed alternative');
$assessment=RequirementAssessmentEvaluator::evaluate($alternative,static fn(string $name)=>$name==='first'?$gap:$pass);
$risk=MagebeanRiskObservation::fromAssessment($alternative,$assessment);
$assert($risk['collection_gaps']===[]&&$risk['collection_complete'],'Verified successful alternative suppresses unnecessary alternative gap');
$alternative['obligations'][0]['proof']='heuristic';
$risk=MagebeanRiskObservation::fromAssessment($alternative,RequirementAssessmentEvaluator::evaluate($alternative,static fn(string $name)=>$name==='first'?$fail:$pass));
$assert($risk['needs_attention'],'Heuristic PASS cannot suppress a real failed observation');
$unresolved=$base;$unresolved['applicability']=['state'=>'UNKNOWN'];
$risk=MagebeanRiskObservation::fromAssessment($unresolved,RequirementAssessmentEvaluator::evaluate($unresolved,static function(){throw new RuntimeException('Must not observe unresolved applicability');}));
$assert(!$risk['needs_attention']&&$risk['findings']===[]&&!$risk['collection_complete']&&$risk['collection_gaps'][0]['reason_code']==='REQUIREMENT_APPLICABILITY_UNRESOLVED','No-check unresolved applicability is a collection/applicability gap');
$unbound=$base;$unbound['review_state']='pending_security_review';$unbound['obligations']=[];
$risk=MagebeanRiskObservation::fromAssessment($unbound,RequirementAssessmentEvaluator::evaluate($unbound,static function(){throw new RuntimeException('No checks should run');}));
$assert(!$risk['needs_attention']&&$risk['findings']===[]&&!$risk['collection_complete']&&$risk['collection_gaps'][0]['reason_code']==='REQUIREMENT_BINDING_UNVALIDATED','No-check unvalidated binding remains an explicit gap');
$supporting=$base;$supporting['obligations'][]=['id'=>'S1','op'=>'all','role'=>'supporting','proof'=>'heuristic','checks'=>[['name'=>'signal']]];
$risk=MagebeanRiskObservation::fromAssessment($supporting,RequirementAssessmentEvaluator::evaluate($supporting,static fn(string $name)=>$name==='signal'?$fail:$pass));
$assert($risk['needs_attention']&&$risk['assessment_outcome']==='PASS','Supporting FAIL is visible without rewriting requirement PASS');
$many=$base;$many['obligations'][0]['checks']=array_fill(0,105,['name'=>'source']);
$risk=MagebeanRiskObservation::fromAssessment($many,RequirementAssessmentEvaluator::evaluate($many,static fn()=>$fail));
$assert(count($risk['findings'])===100&&$risk['findings_truncated']&&$risk['needs_attention']&&!$risk['collection_complete'],'Finding projection is bounded and explicitly truncated');
$risk=MagebeanRiskObservation::fromAssessment($many,RequirementAssessmentEvaluator::evaluate($many,static fn()=>$gap));
$assert(count($risk['collection_gaps'])===100&&$risk['collection_gaps_truncated']&&!$risk['needs_attention']&&!$risk['collection_complete'],'Gap projection is bounded without inventing a finding');
foreach(['family','human']as$guard){$bad=$base;if($guard==='family')$bad['family']='asvs';else$bad['human_evidence']['required']=true;$rejected=false;try{MagebeanRiskObservation::fromAssessment($bad,$assessment);}catch(InvalidArgumentException){$rejected=true;}$assert($rejected,'Reject projection outside automated Magebean '.$guard);}
echo "Magebean risk observation: $count assertions passed\n";
